import json
from collections import defaultdict

with open('/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-11-projects-phase-gated-compound-sparse/360c1b65-5f02-4066-b099-3c31c3a4ff3c/tool-results/mcp-agent-ml-research-read_registry-1778735859376.txt', 'r') as f:
    data = json.load(f)

result = json.loads(data['result'])
experiments = result['data']['experiments']

by_status = defaultdict(list)
for exp_id, exp in experiments.items():
    by_status[exp.get('status', 'UNKNOWN')].append((exp_id, exp))

# Print full details grouped by status
for status in ['RUNNING', 'QUEUED', 'DONE']:
    exps = by_status.get(status, [])
    if not exps:
        continue

    # For DONE, sub-group by conclusion
    if status == 'DONE':
        by_conclusion = defaultdict(list)
        for eid, e in exps:
            by_conclusion[e.get('conclusion', 'N/A')].append((eid, e))

        for conclusion in ['success', 'negative', 'killed', 'failed']:
            sub_exps = by_conclusion.get(conclusion, [])
            if not sub_exps:
                continue
            print(f"\n{'='*70}")
            print(f"STATUS: DONE / CONCLUSION: {conclusion.upper()} ({len(sub_exps)} experiments)")
            print(f"{'='*70}")
            for eid, e in sub_exps:
                hyp = e.get('hypothesis', 'N/A')
                # First line of hypothesis
                hyp_first = hyp.split('\n')[0] if hyp else 'N/A'
                print(f"\n  [{eid}]")
                print(f"    Hypothesis: {hyp_first[:150]}")
                if e.get('metrics'):
                    m = e['metrics']
                    # Print key metrics compactly
                    key_metrics = {}
                    for mk, mv in m.items():
                        if isinstance(mv, (int, float)):
                            key_metrics[mk] = mv
                        elif isinstance(mv, dict) and 'mean' in mv:
                            key_metrics[mk] = f"mean={mv['mean']}"
                    if key_metrics:
                        items = list(key_metrics.items())[:12]
                        print(f"    Metrics: {dict(items)}")
                if e.get('notes'):
                    notes_first = e['notes'].split('\n')[0][:200]
                    print(f"    Notes: {notes_first}")
                if e.get('failure_reason'):
                    print(f"    Failure: {e['failure_reason'][:150]}")
                if e.get('completed_at'):
                    print(f"    Completed: {e['completed_at']}")
    else:
        print(f"\n{'='*70}")
        print(f"STATUS: {status} ({len(exps)} experiments)")
        print(f"{'='*70}")
        for eid, e in exps:
            hyp = e.get('hypothesis', 'N/A')
            hyp_first = hyp.split('\n')[0] if hyp else 'N/A'
            print(f"\n  [{eid}]")
            print(f"    Hypothesis: {hyp_first[:150]}")
            print(f"    Created: {e.get('created_at', 'N/A')}")
            print(f"    Updated: {e.get('updated_at', 'N/A')}")
            if e.get('server'):
                print(f"    Server: {e['server']}, GPU: {e.get('gpu', 'N/A')}")
            if e.get('extra'):
                print(f"    Extra: {e['extra']}")

